public sealed class CapacityCounter
{
    public int Count { get; private set; }
    public int Capacity { get; }

    public CapacityCounter(int capacity)
    {
        if (capacity < 1)
            throw new System.ArgumentOutOfRangeException(
                nameof(capacity));
        Capacity = capacity;
    }

    public bool TryAdd()
    {
        if (Count >= Capacity) return false;
        Count++;
        return true;
    }
}

var counter = new CapacityCounter(5);
for (int i = 0; i < 5; i++)
    counter.TryAdd();
bool accepted = counter.TryAdd();
// accepted == false; counter.Count == 5
